/**
 * A small animal on a wild flower sits on a head as drawn (graphics pass 1, lane PLACE; the owner, 2026-11-16:
 * "grasshoppers seem to be floating next to flowers"). The map's flower point (`islands/wild/map-sampler.ts`) drew it
 * at the plant's middle at its full height: in a clump that is air between the heads (5-18 cm off the nearest), and
 * over a foxglove's spike 26 cm above its top bell. Now: the plant's top head from the asset's own attach points
 * (`flower-heads.json`, generated by `scripts/ark-flower-heads.mjs` from `plants/attach.json`), turned and scaled as
 * the plant is drawn (`AttachPoint.drawn`, read by `micro.ts`); the map's own point, its lists and homes, unchanged.
 */
import assert from "node:assert/strict";
import {readFileSync} from "node:fs";
import {join} from "node:path";
import test from "node:test";
import {setArkWorld} from "@/ark-scene/world";
import {wildScenery} from "@/ark-scene/islands/wild/scenery";
import {flowerHeadAt, wildMapSampler} from "@/ark-scene/islands/wild/map-sampler";
import flowerHeads from "@/ark-scene/flower-heads.json";

setArkWorld("v2");

type Row = {tag: string; p: [number, number, number]};
const attach = JSON.parse(readFileSync(join(process.cwd(), "public/ark/assets/v1/plants/attach.json"), "utf8")) as Record<string, Row[]>;

test("flower-heads.json is the asset library's: each wildflower's top head", () => {
    const flowers = Object.keys(attach).filter((id) => id.startsWith("flower-"));
    assert.equal(Object.keys(flowerHeads.heads).length, flowers.length);
    for (const id of flowers) {
        const top = Math.max(...attach[id].filter((r) => r.tag === "flower_head").map((r) => r.p[1]));
        assert.ok(Math.abs((flowerHeads.heads as Record<string, number[]>)[id][1] - top) < 0.001, id);
    }
});

test("every wild flower's animal is drawn on one of its heads, within 2 mm; none in the air off them; the map's point unchanged", () => {
    const flowers = wildScenery().filter((item) => item.kind === "plant" && item.asset?.startsWith("flower"));
    assert.ok(flowers.length > 100, `${flowers.length} wildflowers`);
    const points = new Map(wildMapSampler().attachPoints().filter((p) => p.tag === "flower_head").map((p) => [p.id, p]));
    let checked = 0;
    let wasOff = 0;
    for (const item of flowers) {
        const point = points.get(`flower@${item.x.toFixed(1)},${item.z.toFixed(1)}`);
        if (!point) continue;
        checked++;
        // Its asset's heads where the plant is drawn: turned by its yaw about +y (three's), scaled, at its foot.
        const c = Math.cos(item.yaw);
        const s = Math.sin(item.yaw);
        const heads = attach[item.asset!].filter((r) => r.tag === "flower_head").map(({p}) => ({x: item.x + (p[0] * c + p[2] * s) * item.scale, y: item.y + p[1] * item.scale, z: item.z + (-p[0] * s + p[2] * c) * item.scale}));
        const drawn = point.drawn!;
        assert.ok(drawn, `${point.id}: drawn on its head`);
        const nearest = Math.min(...heads.map((h) => Math.hypot(h.x - drawn.x, h.y - drawn.y, h.z - drawn.z)));
        assert.ok(nearest < 0.002, `${point.id} (${item.asset}) ${nearest.toFixed(3)} m off its nearest head`);
        // (The map's own point is where it was: its lists and the homes on them, and the server's atlas, unchanged.)
        assert.deepEqual({x: point.x, y: point.y, z: point.z}, {x: item.x, y: item.y + item.height, z: item.z});
        // (Where the map had it before: the middle at the plant's full height.)
        const old = {x: item.x, y: item.y + item.height, z: item.z};
        if (Math.min(...heads.map((h) => Math.hypot(h.x - old.x, h.y - old.y, h.z - old.z))) > 0.03) wasOff++;
        assert.deepEqual(flowerHeadAt(item), drawn);
    }
    console.log(`wild flowers: ${checked} map points on a head; ${wasOff} were over 3 cm off their nearest head before`);
    assert.ok(checked > 100);
});
